# Analyze distance to nearest special value for each changed cell
import math

def manhattan_dist(r1, c1, r2, c2):
    return abs(r1-r2) + abs(c1-c2)

def chebyshev_dist(r1, c1, r2, c2):
    return max(abs(r1-r2), abs(c1-c2))

# Get all special value positions (non-3 in input)
special_values = {}
for r in range(27):
    for c in range(7):
        val = demoin[r][c]
        if val != 3:
            special_values[(r,c)] = val

print(f"Special value positions: {len(special_values)}")

# Compute distance from each changed cell to nearest special value
def nearest_special(r, c):
    min_dist = float('inf')
    best = None
    for (sr, sc) in special_values:
        d = manhattan_dist(r, c, sr, sc)
        if d < min_dist:
            min_dist = d
            best = (sr, sc, special_values[(sr, sc)])
    return min_dist, best

